pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(address logAddr, address secondCaller) public {
        vm.assume(logAddr != address(0));
        vm.assume(secondCaller != address(0));

        bool ok1;
        try c.SetLogFile(logAddr) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        vm.prank(secondCaller);
        try c.SetLogFile(logAddr) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!(ok1 && !ok2));
    }
}
